-- 062_hiking.sql
-- Hiking becomes a sport of its own:
--   - workouts.elevation_gain_m: the metres climbed (D+), from a GPS track
--     or typed, the measure of a hike;
--   - the nutrition references file hiking with the endurance family (an
--     admin can change it in Admin > Nutrition);
--   - two programs in French, English and German: get ready for a multi-day
--     trek, and mountain hiking.
--
-- Deploy: apply this file BEFORE the code: the devices send the new column
-- as soon as the code is out.
--
-- Safe to re-run: the column, an admin's references and the programs already
-- there are kept.

BEGIN;

ALTER TABLE workouts ADD COLUMN IF NOT EXISTS elevation_gain_m INTEGER CHECK (elevation_gain_m IS NULL OR elevation_gain_m BETWEEN 0 AND 20000);

UPDATE app_settings
SET value = jsonb_set(value::jsonb, '{sports,hiking}', '"endurance"')::text,
    updated_at = now()
WHERE key = 'nutrition_guidance'
  AND value::jsonb -> 'sports' -> 'hiking' IS NULL;

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
