SELECT 'Randonnée en montagne', 'Huit semaines pour monter le dénivelé et le redescendre sans casse : renforcement des jambes en freinage, côtes et escaliers, sorties de 400 à 1 000 m de dénivelé positif.', 'endurance', 'intermediate', 3, true, '[{"name":"S1 · Renforcement","week":1,"exercises":[{"exerciseName":"Bulgarian Split Squat","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Step-up","targetSets":4,"targetReps":"10-12","restSec":60},{"exerciseName":"Single-Leg Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":75},{"exerciseName":"Reverse Lunge","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45}]},{"name":"S1 · Côtes et escaliers","week":1,"exercises":[],"cardio":{"sport":"hike","durationMin":49,"intensity":"Zone 3-4","purpose":"Monter en souffle et en puissance, puis redescendre en contrôlant.","steps":["Échauffement : 10 min de marche facile, puis cercles de chevilles et de hanches","4 montées de 3 min à bon rythme (côte ou escaliers), redescente en marchant lentement","Retour au calme : 5 à 10 min de marche lente, puis étirements des mollets et des cuisses"],"notes":"Les bâtons soulagent les genoux en descente et aident en montée : réglez-les à hauteur de coude."}},{"name":"S1 · Sortie avec dénivelé","week":1,"exercises":[],"cardio":{"sport":"hike","durationMin":180,"intensity":"Zone 2","purpose":"Monter le dénivelé à une allure qu''on tient longtemps, et ménager les genoux en descente.","steps":["Échauffement : 10 min de marche facile, puis cercles de chevilles et de hanches","Environ 400 m de dénivelé positif sur 3 h, montée à allure régulière","En descente : petits pas, genoux souples, bâtons si vous en avez","Retour au calme : 5 à 10 min de marche lente, puis étirements des mollets et des cuisses"],"notes":"Freiner les descentes : c''est là que les genoux et le