SELECT 'Get ready for a multi-day trek', 'Eight weeks to carry a heavier pack for longer and set off again the next day: leg and trunk strength, a walk in the week, a long outing at the weekend, up to two days back to back.', 'endurance', 'beginner', 3, true, '[{"name":"W1 · Strength","week":1,"exercises":[{"exerciseName":"Goblet Squat","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Step-up","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Side Plank","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Bird Dog","targetSets":3,"targetReps":"10","restSec":45}]},{"name":"W1 · Brisk walk","week":1,"exercises":[],"cardio":{"sport":"hike","durationMin":45,"intensity":"Zone 2","purpose":"Walk at a good pace with a pack, to get the body used to it without wearing it out.","steps":["Warm-up: 10 min of easy walking, then ankle and hip circles","30 min of brisk walking (you can talk but not sing)","Cool-down: 5 to 10 min of slow walking, then calf and thigh stretches"]}},{"name":"W1 · Long outing","week":1,"exercises":[],"cardio":{"sport":"hike","durationMin":120,"intensity":"Zone 1-2","purpose":"Lengthen the time on your feet and the weight of the pack, without hurrying.","steps":["Warm-up: 10 min of easy walking, then ankle and hip circles","2 h of hiking at a steady pace, 5 kg pack","Cool-down: 5 to 10 min of slow walking, then calf and thigh stretches"],"notes":"Before you go: route left with someone, weather checked, water, food, a warm layer, a first-aid kit and a charged phone."}},{"name":"W2 · Strength","week":2,"exercises":[{"exerciseName":"Goblet Squat","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Step-up","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-