INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Vorbereitung auf ein mehrtägiges Trekking', 'Acht Wochen, um einen schwereren Rucksack länger zu tragen und am nächsten Tag wieder loszugehen: Bein- und Rumpfkraft, Gehen unter der Woche, lange Tour am Wochenende, bis zu zwei Tagen am Stück.', 'endurance', 'beginner', 3, true, '[{"name":"W1 · Kräftigung","week":1,"exercises":[{"exerciseName":"Goblet Squat","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Step-up","targetSets":3,"targetReps":"10-12","restSec":60},{"exerciseName":"Single-Leg Calf Raise","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":45},{"exerciseName":"Side Plank","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Bird Dog","targetSets":3,"targetReps":"10","restSec":45}]},{"name":"W1 · Zügiges Gehen","week":1,"exercises":[],"cardio":{"sport":"hike","durationMin":45,"intensity":"Zone 2","purpose":"Zügig mit Rucksack gehen, um den Körper zu gewöhnen, ohne ihn zu verschleißen.","steps":["Aufwärmen: 10 Min. lockeres Gehen, dann Knöchel- und Hüftkreisen","30 Min. zügiges Gehen (sprechen geht, singen nicht)","Ausklang: 5 bis 10 Min. langsames Gehen, dann Waden und Oberschenkel dehnen"]}},{"name":"W1 · Lange Tour","week":1,"exercises":[],"cardio":{"sport":"hike","durationMin":120,"intensity":"Zone 1-2","purpose":"Zeit auf den Beinen und Rucksackgewicht steigern, ohne Eile.","steps":["Aufwärmen: 10 Min. lockeres Gehen, dann Knöchel- und Hüftkreisen","2 h Wandern in gleichmäßigem Tempo, Rucksack 5 kg","Ausklang: 5 bis 10 Min. langsames Gehen, dann Waden und Oberschenkel dehnen"],"notes":"Vor dem Aufbruch: Route bei jemandem hinterlassen, Wetter geprüft, Wasser, Essen, eine warme Schicht, ein Erste-Hilfe-Set und ein geladenes Handy."}},{"name":"W2 · Kräftigung","week":2,"exercises":[{"exerciseName":"Goblet Squat","targetSets":3,"targetReps":"10-12","restSec":75},{"exerciseName":"Step-up","targetSets":3,"targetReps":"10-12","restSec":60},{"exe